pm.test("Status code harus 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response berupa array", function () {
    const response = pm.response.json();

    pm.expect(response).to.be.an("array");
});

pm.test("Setiap booking memiliki bookingid", function () {
    const response = pm.response.json();

    response.forEach(function (booking) {
        pm.expect(booking).to.have.property("bookingid");
    });
});

pm.test("Booking ID harus berupa angka", function () {
    const response = pm.response.json();

    response.forEach(function (booking) {
        pm.expect(booking.bookingid).to.be.a("number");
    });
});

pm.test("Booking data tidak boleh kosong", function () {
    const response = pm.response.json();

    pm.expect(response).to.be.an("array").that.is.not.empty;
});

pm.test("Menampilkan total booking", function () {
    const response = pm.response.json();

    const totalBooking = response.length;

    console.log("Total Booking:", totalBooking);

    pm.expect(totalBooking).to.be.greaterThan(0);
});
